    @Test void associationReflectsPostParseChanges() {
        String html = "<form id='a'><input id='i' name='n' value='1'></form><form id='b'></form>";
        Document doc = Jsoup.parse(html);
        FormElement a = doc.expectForm("#a");
        FormElement b = doc.expectForm("#b");
        Element input = doc.expectForm("#a").elements().first();

        // add a form attribute: re-home from ancestor form a to form b
        input.attr("form", "b");
        assertEquals(0, a.formData().size());
        assertEquals("n=1", b.formData().get(0).toString());

        // remove it: falls back to... no ancestor now (it is still a child of form a's subtree)
        input.removeAttr("form");
        assertEquals("n=1", a.formData().get(0).toString());
        assertEquals(0, b.formData().size());

        // change the referenced form's id
        input.attr("form", "a");
        b.attr("id", "a"); // now both forms share id a; first match is form a
        assertEquals("n=1", a.formData().get(0).toString());

        // physically move the control outside both forms; explicit attr still resolves
        doc.body().appendChild(input);
        input.attr("form", "b");
        // form a is still first with id=a; input references b, now only on form... change b back
        b.attr("id", "b");
        assertEquals(0, a.formData().size());
        assertEquals("n=1", b.formData().get(0).toString());
    }

