    Validate.isFalse(child == this, CycleError);
    if (child.childNodeSize() == 0) return;

    for (Node ancestor = parentNode; ancestor != null; ancestor = ancestor.parentNode)
        Validate.isFalse(ancestor == child, CycleError);
