import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.Connection;
import java.util.List;

public class EdgeCheck {
  static void check(String label, Object actual, Object expected) {
    boolean ok = String.valueOf(actual).equals(String.valueOf(expected));
    System.out.println((ok ? "PASS " : "FAIL ") + label + " -> " + actual + (ok ? "" : " (expected " + expected + ")"));
  }
  static String data(FormElement f) {
    StringBuilder sb = new StringBuilder();
    for (Connection.KeyVal kv : f.formData()) sb.append(kv.key()).append('=').append(kv.value()).append(';');
    return sb.toString();
  }
  public static void main(String[] a) {
    // form removed from doc: form=attr controls become unowned
    Document d1 = Jsoup.parse("<form id=f></form><input name=x value=1 form=f>");
    FormElement f1 = d1.expectForm("#f");
    check("before remove", data(f1), "x=1;");
    f1.remove();
    check("form removed, control unowned", d1.select("input").first().ownerDocument() != null, "true");
    // control now has no owner; nothing to query on f1 (detached) - just ensure no exception
    check("detached form data", data(f1), "");

    // changing form id dynamically
    Document d2 = Jsoup.parse("<form id=f></form><input name=x value=1 form=f>");
    FormElement f2 = d2.expectForm("#f");
    f2.attr("id", "g");
    check("id changed, ref dangles", data(f2), "");
    f2.attr("id", "f");
    check("id restored", data(f2), "x=1;");

    // control moved to another document
    Document d3 = Jsoup.parse("<form id=f><input name=x value=1></form>");
    Document d4 = Jsoup.parse("<form id=h></form>");
    FormElement f3 = d3.expectForm("#f");
    FormElement f4 = d4.expectForm("#h");
    Element in = d3.selectFirst("input");
    f4.appendChild(in); // cross-doc move into another form
    check("cross-doc: source form", data(f3), "");
    check("cross-doc: target form", data(f4), "x=1;");

    // moving the form itself keeps subtree controls
    Document d5 = Jsoup.parse("<body><div id=wrap></div><form id=f><input name=x value=1></form>");
    FormElement f5 = d5.expectForm("#f");
    d5.selectFirst("#wrap").appendChild(f5);
    check("form moved, controls kept", data(f5), "x=1;");

    // fragment append into a form (foster case inside table)
    Document d6 = Jsoup.parse("<form id=f><table id=t></table></form>");
    FormElement f6 = d6.expectForm("#f");
    d6.selectFirst("#t").append("<input name=x value=1>");
    check("fragment input fostered in-table inside form", data(f6), "x=1;");

    // empty select with only disabled optgroup option -> empty
    Document d7 = Jsoup.parse("<form><select name=s><optgroup disabled><option value=1></optgroup></select></form>");
    check("only disabled optgroup option", data(d7.expectForm("form")), "");

    // textarea takes text; submit included; image excluded
    Document d8 = Jsoup.parse("<form><textarea name=t>hello</textarea><input type=submit name=s value=Go><input type=image name=i value=x></form>");
    check("textarea+submit, no image", data(d8.expectForm("form")), "t=hello;s=Go;");

    // duplicate names keep doc order incl. outside form= control
    Document d9 = Jsoup.parse("<input name=a value=0 form=f><form id=f><input name=a value=1></form>");
    check("outside-before order", data(d9.expectForm("#f")), "a=0;a=1;");
  }
}
